ORDER BY updated_at DESC, id DESC

mapper.update:
UPDATE report_definition
SET name = #{name}, description = #{description}, cadence = #{cadence},
    template_key = #{templateKey}, config_json = #{configJson}
WHERE workspace_id = #{workspaceId} AND id = #{id}

mapper.select:
SELECT id, report_definition_id, period_start, period_end, origin, generated_by, generated_at
FROM report_snapshot
WHERE workspace_id = #{workspaceId} AND report_definition_id = #{reportDefinitionId}
ORDER BY generated_at DESC, id DESC
LIMIT #{limit}

SELECT  FROM report_snapshot
WHERE workspace_id = #{workspaceId}
  AND report_definition_id = #{reportDefinitionId}
  AND id = #{id}

SELECT COUNT(*) FROM report_snapshot
WHERE workspace_id = #{workspaceId}
  AND report_definition_id = #{reportDefinitionId}
  AND origin = 'manual'

SELECT COUNT(*) FROM report_snapshot
WHERE workspace_id = #{workspaceId}
  AND report_definition_id = #{reportDefinitionId}

SELECT COUNT(*) FROM report_snapshot
WHERE workspace_id = #{workspaceId}
  AND report_definition_id = #{reportDefinitionId}
  AND (generated_by IS NULL OR generated_by <> #{generatedBy})

SELECT COUNT(*) FROM report_snapshot
WHERE workspace_id = #{workspaceId}
  AND report_definition_id = #{reportDefinitionId}
  AND origin = 'scheduled'

SELECT COALESCE(SUM(OCTET_LENGTH(computed_result)), 0)
FROM report_snapshot
WHERE workspace_id = #{workspaceId}

mapper.delete:
DELETE FROM report_snapshot
WHERE workspace_id = #{workspaceId}
  AND origin = 'scheduled'
  AND (
    report_schedule_id = #{reportScheduleId}
    OR (report_schedule_id IS NULL AND report_definition_id = #{reportDefinitionId})
  )
  AND id NOT IN (
    SELECT id FROM (
      SELECT id FROM report_snapshot
      WHERE workspace_id = #{workspaceId}
        AND origin = 'scheduled'
        AND (
          report_schedule_id = #{reportScheduleId}
          OR (report_schedule_id IS NULL AND report_definition_id = #{reportDefinitionId})
        )
      ORDER BY generated_at DESC, id DESC
      LIMIT #{keepCount}
    ) AS keep_rows
  )

DELETE FROM report_snapshot
WHERE workspace_id = #{workspaceId}
  AND origin = 'scheduled'
ORDER BY generated_at ASC, id ASC
LIMIT #{limit}

DELETE FROM report_snapshot
WHERE workspace_id = #{workspaceId}
  AND report_definition_id = #{reportDefinitionId}
  AND report_schedule_id IS NULL
  AND origin = 'scheduled'

DELETE FROM report_snapshot
WHERE workspace_id = #{workspaceId}
  AND report_definition_id = #{reportDefinitionId}
  AND id = #{id}

