mapper.select:
SELECT  AS group_key,
        AS group_label,
       'count' AS unit,
       COUNT(*) AS value
FROM person_employment employment
JOIN person ON person.id = employment.person_id
  AND person.workspace_id = #{query.workspaceId}
WHERE employment.workspace_id = #{query.workspaceId}
  AND person.suspended_at IS NULL
  AND  >= #{query.startUtc}
  AND  < #{query.endUtc}

  AND EXISTS (
    SELECT 1
    FROM person_employment prior_employment
    WHERE prior_employment.workspace_id = #{query.workspaceId}
      AND prior_employment.person_id = employment.person_id
      AND prior_employment.id <> employment.id
      AND prior_employment.ended_at IS NOT NULL
      AND prior_employment.ended_at <= employment.started_at
  )


  AND person.owner_id IN
  #{id}


  AND EXISTS (
    SELECT 1
    FROM person_tag employment_person_tag
    JOIN tag employment_tag ON employment_tag.id = employment_person_tag.tag_id
      AND employment_tag.workspace_id = #{query.workspaceId}
    WHERE employment_person_tag.person_id = person.id
      AND employment_person_tag.tag_id IN
      #{id}
  )

GROUP BY group_key, group_label
ORDER BY group_key

